#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int RGB1_R = 2;     
const int RGB1_G = 3;     
const int RGB1_B = 4;     
const int RGB2_R = 5;     
const int RGB2_G = 6;     
const int RGB2_B = 7;     
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000, 
};
int currentNumber = 0;
int colorIndex = 0;
unsigned long lastUpdateTime = 0;
const int colors[][3] = {
  {255, 0, 0},   
  {0, 255, 0},   
  {0, 0, 255},   
  {255, 255, 0}, 
  {0, 255, 255}, 
  {255, 0, 255}, 
  {255, 255, 255}
};

void setup();
void loop();
void displayNumber(int number);
void setRGBColor(int red, int green, int blue);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(RGB1_R, OUTPUT);
  pinMode(RGB1_G, OUTPUT);
  pinMode(RGB1_B, OUTPUT);
  pinMode(RGB2_R, OUTPUT);
  pinMode(RGB2_G, OUTPUT);
  pinMode(RGB2_B, OUTPUT);
  displayNumber(0); 
  setRGBColor(colors[0][0], colors[0][1], colors[0][2]); 
  lastUpdateTime = millis();
}
void loop() {
  unsigned long currentTime = millis();
  if (currentTime - lastUpdateTime >= 2000) {
    lastUpdateTime = currentTime;
    currentNumber++;
    if (currentNumber > 99) {
      currentNumber = 0;
    }
    displayNumber(currentNumber);
    colorIndex = (colorIndex + 1) % 7;
    setRGBColor(colors[colorIndex][0], colors[colorIndex][1], colors[colorIndex][2]);
  }
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void setRGBColor(int red, int green, int blue) {
  analogWrite(RGB1_R, red);
  analogWrite(RGB1_G, green);
  analogWrite(RGB1_B, blue);
  analogWrite(RGB2_R, red);
  analogWrite(RGB2_G, green);
  analogWrite(RGB2_B, blue);
}
